insert into public.vocabulary(id,hanzi,pinyin,meaning_vi,syllabus_version,is_published) values('你好','你好','nǐ hǎo','Xin chào','book1-preview-v1',false) on conflict(id) do nothing;
insert into public.lessons(id,unit_id,title,description,estimated_minutes,sort_order,content_json,is_published) values('hanzione-b1-l01a','hanzione-b1-ch01','Quyển 1 · Bài 1A: 你好 – Xin chào','Lời chào đầu tiên: nghe, hiểu, tự nhớ và tự viết. Không cần biết tiếng Trung trước.',15,(select coalesce(max(sort_order),-1)+1 from public.lessons where unit_id='hanzione-b1-ch01'),'{"id":"hanzione-b1-l01a","title":"Quyển 1 · Bài 1A: 你好 – Xin chào","description":"Lời chào đầu tiên: nghe, hiểu, tự nhớ và tự viết. Không cần biết tiếng Trung trước.","minutes":15,"guide":"Bạn gặp một người bạn mới. Hôm nay, bạn sẽ học cách nói Xin chào, nhận ra hai chữ trong lời chào và thử viết chúng vào vở. Chỉ ba mục từ mới, học từng chút một.","words":[{"hanzi":"你","pinyin":"nǐ","meaning":"Bạn","tones":[3],"example":{"hanzi":"你好","pinyin":"nǐ hǎo","meaning":"Xin chào — 你 chỉ người bạn đang chào."}},{"hanzi":"好","pinyin":"hǎo","meaning":"Tốt","tones":[3],"example":{"hanzi":"你好","pinyin":"nǐ hǎo","meaning":"Xin chào — 好 đứng sau 你 trong lời chào."}},{"hanzi":"你好","pinyin":"nǐ hǎo","meaning":"Xin chào","tones":[3,3],"example":{"hanzi":"你好","pinyin":"nǐ hǎo","meaning":"Bạn gặp một người bạn mới và chào: Xin chào!"}}],"questions":[{"type":"quiz","prompt":"你好 có nghĩa là gì?","options":["Xin chào","Bạn","Tốt"],"answer":"Xin chào","explanation":"你好 là lời chào: Xin chào. Hãy nhớ nghĩa của cả cụm.","hint":"Bạn dùng cả cụm khi gặp một người bạn mới.","knowledge":["greeting-nihao"],"contentId":"hanzione-b1-l01a:check-meaning","key":"[\"quiz\",\"你好 có nghĩa là gì?\",\"\",\"hanzione-b1-l01a:check-meaning\"]","targets":["你","好","你好"]},{"type":"quiz","prompt":"你 có nghĩa là gì?","options":["Bạn","Tốt","Xin chào"],"answer":"Bạn","explanation":"你 nghĩa là Bạn, chỉ người đang nói chuyện với mình.","hint":"Đây là chữ đầu tiên trong lời chào.","knowledge":["word-ni"],"contentId":"hanzione-b1-l01a:check-ni","key":"[\"quiz\",\"你 có nghĩa là gì?\",\"\",\"hanzione-b1-l01a:check-ni\"]","targets":["你"]},{"type":"quiz","prompt":"Pinyin của cả lời chào 你好 là gì?","options":["nǐ hǎo","nǐ","hǎo"],"answer":"nǐ hǎo","explanation":"Hai chữ 你好 có hai âm nǐ hǎo; cả hai đều viết dấu thanh 3. Khi nói liền, âm đầu thường nghe gần thanh 2.","hint":"Cần đủ hai âm, theo thứ tự chữ trong lời chào.","knowledge":["greeting-nihao","tone-three-pair"],"contentId":"hanzione-b1-l01a:check-pinyin","key":"[\"quiz\",\"Pinyin của cả lời chào 你好 là gì?\",\"\",\"hanzione-b1-l01a:check-pinyin\"]","targets":["你","好","你好"]},{"type":"sentence","prompt":"Bạn gặp một người bạn mới. Ghép lời chào Xin chào.","options":["好","你"],"answer":"你好","explanation":"Lời chào là 你好: chữ 你 đứng trước chữ 好.","hint":"Bạn đứng trước Tốt trong cụm đã học.","knowledge":["greeting-nihao","word-ni","word-hao"],"contentId":"hanzione-b1-l01a:check-order","key":"[\"sentence\",\"Bạn gặp một người bạn mới. Ghép lời chào Xin chào.\",\"\",\"hanzione-b1-l01a:check-order\"]","targets":["你","好","你好"]},{"type":"match","prompt":"Ghép ba mục từ với nghĩa đã học.","options":["你|Bạn","好|Tốt","你好|Xin chào"],"answer":"matched","explanation":"你 là Bạn, 好 là Tốt, còn cả cụm 你好 là Xin chào.","hint":"Phân biệt nghĩa từng chữ và nghĩa của cả lời chào.","knowledge":["word-ni","word-hao","greeting-nihao"],"contentId":"hanzione-b1-l01a:check-match","key":"[\"match\",\"Ghép ba mục từ với nghĩa đã học.\",\"\",\"hanzione-b1-l01a:check-match\"]","targets":["你","好","你好"]}],"writing":"Quan sát hai chữ trong mẫu bên dưới, rồi chép chậm. Chữ chỉ Bạn có phần chỉ người bên trái; chữ nghĩa Tốt gồm phần nữ bên trái và phần con bên phải. Đây là gợi ý nhận hình, chưa phải bài dạy đầy đủ thứ tự nét. Ô viết trên màn hình chỉ để thử; ứng dụng chưa chấm chữ hay nét viết.","learning":{"schemaVersion":2,"id":"hanzione-b1-l01a","chapterId":"hanzione-b1-ch01","title":"Quyển 1 · Bài 1A: 你好 – Xin chào","description":"Lời chào đầu tiên: nghe, hiểu, tự nhớ và tự viết. Không cần biết tiếng Trung trước.","minutes":15,"difficulty":1,"status":"draft","prerequisites":[],"screens":[{"id":"welcome","title":"1/7 · Lời chào đầu tiên","body":"Bạn gặp một người bạn mới. Hôm nay, bạn sẽ học cách nói Xin chào, nhận ra hai chữ trong lời chào và thử viết chúng vào vở. Chỉ ba mục từ mới, học từng chút một.","theory":"Tiếng Trung dùng chữ Hán để viết. Pinyin là cách ghi âm bằng chữ Latin giúp bạn đọc chữ Hán; dấu trên nguyên âm cho biết thanh điệu. Bạn chưa cần thuộc toàn bộ Pinyin hay thanh điệu. Hãy bắt đầu bằng một lời chào và nghe trước khi tự nói.","introduces":["pinyin-purpose"],"examples":[],"steps":["Học ba mục từ, nghe và đọc theo.","Che đáp án để tự nhớ, rồi viết vào vở.","Làm năm hoạt động kiểm tra, xem lại lỗi và chuẩn bị lịch ôn."],"kind":"objective"},{"id":"words","title":"2/7 · Ba mục từ của hôm nay","body":"Chạm vào từng từ để nghe. 你 chỉ người đang nói chuyện với bạn. 好 nghĩa là tốt; ghép 你 rồi 好 thành lời chào 你好. Trong lời chào, hãy nhớ nghĩa cả cụm là Xin chào, không dịch từng chữ thành Bạn tốt.","introduces":["word-ni","word-hao","greeting-nihao"],"examples":[],"steps":[],"kind":"vocabulary","words":[{"hanzi":"你","pinyin":"nǐ","meaning":"Bạn","tones":[3],"example":{"hanzi":"你好","pinyin":"nǐ hǎo","meaning":"Xin chào — 你 chỉ người bạn đang chào."}},{"hanzi":"好","pinyin":"hǎo","meaning":"Tốt","tones":[3],"example":{"hanzi":"你好","pinyin":"nǐ hǎo","meaning":"Xin chào — 好 đứng sau 你 trong lời chào."}},{"hanzi":"你好","pinyin":"nǐ hǎo","meaning":"Xin chào","tones":[3,3],"example":{"hanzi":"你好","pinyin":"nǐ hǎo","meaning":"Bạn gặp một người bạn mới và chào: Xin chào!"}}]},{"id":"listen-speak","title":"3/7 · Nghe rồi nói theo","body":"Hai âm trong lời chào đều viết dấu ˇ (thanh 3). Khi đứng một mình, thanh 3 có thể hạ xuống rồi nhấc lên; trong lời nói liền, không cần cố kéo dài. Khi hai thanh 3 đi liền nhau, thanh đầu thường đọc gần thanh 2 (giọng đi lên). Cách viết Pinyin của lời chào vẫn giữ hai dấu thanh 3. Hãy nghe cả cụm và bắt chước nhịp nói.","introduces":["tone-three-pair"],"examples":[{"hanzi":"你好","pinyin":"nǐ hǎo","meaning":"Xin chào · Pinyin chuẩn để ghi nhớ"}],"steps":["Nghe lời chào hai lần; dùng Nghe chậm nếu cần.","Đọc theo ba lần, nghỉ một nhịp giữa mỗi lần.","Ẩn Pinyin và thử đọc lại chữ Hán. Chưa chắc thì nghe lại; chưa cần nói hoàn hảo."],"kind":"pronunciation","speech":"你好"},{"id":"remember","title":"4/7 · Tự nhớ trước khi xem","body":"Đừng đoán bằng cách nhìn lựa chọn. Hãy tự nói hoặc viết đáp án, rồi lật thẻ để đối chiếu. Chưa nhớ là tín hiệu để ôn sớm; tự đánh giá không cộng điểm hay XP.","introduces":[],"examples":[],"steps":[],"kind":"recall","cards":[{"id":"greeting-meaning","prompt":"你好 có nghĩa là gì?","answer":"Xin chào","answerType":"meaning","hint":"Bạn dùng cụm này khi gặp người bạn mới.","hanzi":"你好","knowledge":["greeting-nihao"]},{"id":"greeting-write","prompt":"Xin chào — nói hoặc viết bằng tiếng Trung, không nhìn mẫu.","answer":"你好","answerType":"hanzi","hint":"Chữ chỉ Bạn đứng trước, chữ nghĩa Tốt đứng sau.","hanzi":"你好","knowledge":["greeting-nihao"]},{"id":"ni-meaning","prompt":"你 có nghĩa là gì?","answer":"Bạn","answerType":"meaning","hint":"Chỉ người đang nói chuyện với mình.","hanzi":"你","knowledge":["word-ni"]},{"id":"hao-meaning","prompt":"好 có nghĩa là gì?","answer":"Tốt","answerType":"meaning","hint":"Một từ mang nghĩa tích cực, cũng nằm ở cuối lời chào.","hanzi":"好","knowledge":["word-hao"]},{"id":"greeting-pinyin","prompt":"你好 — hãy nói Pinyin, nhớ cả dấu thanh.","answer":"nǐ hǎo","answerType":"pinyin","hint":"Cả hai âm đều viết thanh 3, dấu ˇ.","hanzi":"你好","knowledge":["greeting-nihao","tone-three-pair"]}]},{"id":"notebook","title":"5/7 · Lấy vở ra nào","body":"Quan sát hai chữ trong mẫu bên dưới, rồi chép chậm. Chữ chỉ Bạn có phần chỉ người bên trái; chữ nghĩa Tốt gồm phần nữ bên trái và phần con bên phải. Đây là gợi ý nhận hình, chưa phải bài dạy đầy đủ thứ tự nét. Ô viết trên màn hình chỉ để thử; ứng dụng chưa chấm chữ hay nét viết.","introduces":[],"examples":[{"hanzi":"你","pinyin":"nǐ","meaning":"Bạn · cấu tạo nhìn hình: 亻 + 尔"},{"hanzi":"好","pinyin":"hǎo","meaning":"Tốt · cấu tạo nhìn hình: 女 + 子"},{"hanzi":"你好","pinyin":"nǐ hǎo","meaning":"Xin chào"}],"steps":[],"kind":"notebook","checklist":["Đã viết mỗi chữ đơn ba lần và cả lời chào hai lần vào vở.","Đã che mẫu, nhìn nghĩa Xin chào và tự viết lại một lần.","Đã hiện mẫu để đối chiếu vị trí các phần, Pinyin và nghĩa; sửa chỗ mình chưa nhớ."]},{"id":"check","title":"6/7 · Thử dùng điều vừa học","body":"Năm hoạt động chỉ dùng ba mục từ vừa học. Mỗi lỗi đều có giải thích. Nếu chưa đạt 70%, hãy tự nhớ lại trước khi kết thúc.","introduces":[],"examples":[],"steps":[],"kind":"assessment","items":[{"id":"meaning","phase":"final","question":{"type":"quiz","prompt":"你好 có nghĩa là gì?","options":["Xin chào","Bạn","Tốt"],"answer":"Xin chào","explanation":"你好 là lời chào: Xin chào. Hãy nhớ nghĩa của cả cụm.","hint":"Bạn dùng cả cụm khi gặp một người bạn mới.","knowledge":["greeting-nihao"]}},{"id":"ni","phase":"final","question":{"type":"quiz","prompt":"你 có nghĩa là gì?","options":["Bạn","Tốt","Xin chào"],"answer":"Bạn","explanation":"你 nghĩa là Bạn, chỉ người đang nói chuyện với mình.","hint":"Đây là chữ đầu tiên trong lời chào.","knowledge":["word-ni"]}},{"id":"pinyin","phase":"final","question":{"type":"quiz","prompt":"Pinyin của cả lời chào 你好 là gì?","options":["nǐ hǎo","nǐ","hǎo"],"answer":"nǐ hǎo","explanation":"Hai chữ 你好 có hai âm nǐ hǎo; cả hai đều viết dấu thanh 3. Khi nói liền, âm đầu thường nghe gần thanh 2.","hint":"Cần đủ hai âm, theo thứ tự chữ trong lời chào.","knowledge":["greeting-nihao","tone-three-pair"]}},{"id":"order","phase":"application","question":{"type":"sentence","prompt":"Bạn gặp một người bạn mới. Ghép lời chào Xin chào.","options":["好","你"],"answer":"你好","explanation":"Lời chào là 你好: chữ 你 đứng trước chữ 好.","hint":"Bạn đứng trước Tốt trong cụm đã học.","knowledge":["greeting-nihao","word-ni","word-hao"]}},{"id":"match","phase":"final","question":{"type":"match","prompt":"Ghép ba mục từ với nghĩa đã học.","options":["你|Bạn","好|Tốt","你好|Xin chào"],"answer":"matched","explanation":"你 là Bạn, 好 là Tốt, còn cả cụm 你好 là Xin chào.","hint":"Phân biệt nghĩa từng chữ và nghĩa của cả lời chào.","knowledge":["word-ni","word-hao","greeting-nihao"]}}]},{"id":"review-plan","title":"7/7 · Nhớ lâu bằng những lần ôn ngắn","body":"Bạn vừa học lời chào đầu tiên. Năm hướng tự nhớ sẽ tiếp tục được luyện: chữ → nghĩa, nghĩa Xin chào → chữ, từng chữ → nghĩa và lời chào → Pinyin. Các hướng của cùng một từ dùng chung lịch ôn; nếu một hướng chưa nhớ, cả từ được ôn sớm. Bản xem trước chỉ cho xem kế hoạch, không lưu lịch hay XP.","introduces":[],"examples":[],"steps":["Khi bài đã xuất bản và bạn lưu kết quả: từ sai hoặc tự đánh giá Chưa nhớ được hẹn lại sau 10 phút.","Từ nhớ được hẹn sau 1 ngày; các lần đúng tiếp theo tăng khoảng cách, tối đa 30 ngày. Lịch thích ứng theo lần ôn thực tế.","Vào Luyện tập để lật thẻ, luyện nghe, nghĩa hoặc Pinyin; vào Viết để nhìn nghĩa và tự viết lại vào vở.","Tự đánh giá không cộng XP. Điểm kiểm tra là phần riêng; đạt từ 70% để hoàn thành bài."],"kind":"srs"}]},"prerequisites":[]}'::jsonb,false);
